import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.B0p3fmqd.js";const m=JSON.parse('{"title":"Common issues","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/common-issues.md","filePath":"troubleshooting/common-issues.md","lastUpdated":null}'),r={name:"troubleshooting/common-issues.md"};function i(n,e,h,d,c,l){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="common-issues" tabindex="-1">Common issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common issues&quot;">​</a></h1><h2 id="the-script-does-not-start" tabindex="-1">The script does not start <a class="header-anchor" href="#the-script-does-not-start" aria-label="Permalink to &quot;The script does not start&quot;">​</a></h2><ul><li>Check that <code>community_bridge</code>, <code>ox_lib</code> and <code>oxmysql</code> are started <strong>before</strong> the script.</li><li>Make sure the resource folder name matches the name in your <code>ensure</code> line.</li><li>Read the first red line in the server console. It usually names the missing dependency.</li></ul><h2 id="tables-are-missing-or-sql-errors-appear" tabindex="-1">Tables are missing or SQL errors appear <a class="header-anchor" href="#tables-are-missing-or-sql-errors-appear" aria-label="Permalink to &quot;Tables are missing or SQL errors appear&quot;">​</a></h2><p>Each script creates its own tables on first start, so there is no SQL file to import. Make sure the database user has permission to create tables, then restart the server.</p><h2 id="the-setup-command-says-i-do-not-have-permission" tabindex="-1">The setup command says I do not have permission <a class="header-anchor" href="#the-setup-command-says-i-do-not-have-permission" aria-label="Permalink to &quot;The setup command says I do not have permission&quot;">​</a></h2><p>Add the permission from the script&#39;s installation page to your permissions cfg and restart. Admin commands are locked behind an ace.</p><h2 id="an-item-has-no-icon-or-does-not-exist" tabindex="-1">An item has no icon or does not exist <a class="header-anchor" href="#an-item-has-no-icon-or-does-not-exist" aria-label="Permalink to &quot;An item has no icon or does not exist&quot;">​</a></h2><p>Add the items listed on the script&#39;s installation page to your inventory, and copy the icons into your inventory&#39;s images folder. Item names must match exactly.</p><h2 id="targets-or-zones-are-hard-to-see" tabindex="-1">Targets or zones are hard to see <a class="header-anchor" href="#targets-or-zones-are-hard-to-see" aria-label="Permalink to &quot;Targets or zones are hard to see&quot;">​</a></h2><p>Set <code>Config.Debug = true</code> in the script&#39;s config to draw the zones and print what the script is doing. Turn it back off on a live server.</p><h2 id="the-server-crashes-when-two-scripts-load-the-same-props" tabindex="-1">The server crashes when two scripts load the same props <a class="header-anchor" href="#the-server-crashes-when-two-scripts-load-the-same-props" aria-label="Permalink to &quot;The server crashes when two scripts load the same props&quot;">​</a></h2><p>Two resources must not ask the game to load the same prop file. If the server crashes while starting, and you run Tow Scenarios together with <code>p_ambulancejob</code>, both manifests contain</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data_file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;DLC_ITYP_REQUEST&#39; &#39;stream/mads.ytyp&#39;</span></span></code></pre></div><p>Comment that line out in the <code>fxmanifest.lua</code> of <code>filthy_towscenarios</code> (put <code>--</code> in front of it) and leave it in <code>p_ambulancejob</code>. Restart the server. If it still crashes, do the same for any other <code>DLC_ITYP_REQUEST</code> line that both resources share.</p><h2 id="my-edits-were-lost-after-an-update" tabindex="-1">My edits were lost after an update <a class="header-anchor" href="#my-edits-were-lost-after-an-update" aria-label="Permalink to &quot;My edits were lost after an update&quot;">​</a></h2><p>Only the config files listed on each script&#39;s configuration page are kept open for editing. Edits to any other file are overwritten when you update.</p>',17)])])}const u=s(r,[["render",i]]);export{m as __pageData,u as default};
